static void die(const char *what) {
    fprintf(stderr, "DESKTOP_BOOT_FAILED %s errno=%d %s\n", what, errno, strerror(errno));
    for (;;) sleep(60);
}
static void filesystem(const char *dev, const char *path, const char *type, unsigned long flags, const char *opts) {
    if (mount(dev, path, type, flags, opts)) die(path);
}
static const char *disk(const char *serial) {
    static char devices[5][16]; static int slot;
    for (int attempt=0;attempt<60;attempt++) {
        for (char letter='a';letter<='e';letter++) {
            char path[128],value[128]={0};
            snprintf(path,sizeof(path),"/sys/block/vd%c/serial",letter);
            int fd=open(path,O_RDONLY);
            if(fd<0) continue;
            ssize_t n=read(fd,value,sizeof(value)-1); close(fd);
            if(n<=0) continue;
            value[strcspn(value,"\r\n")]=0;
            if(!strcmp(value,serial)) {
                snprintf(devices[slot],16,"/dev/vd%c",letter);
                return devices[slot++];
            }
        }
        sleep(1);
    }
    errno=ENODEV; die(serial); return NULL;
}

#include <dirent.h>
#include <sys/ioctl.h>
#include <linux/fb.h>
static void display_node(const char *path) {
    struct stat st; int r=stat(path,&st); int e=errno;
    printf("DISPLAY848_NODE path=%s stat=%d errno=%d",path,r,e);
    if(!r)printf(" mode=%o uid=%u gid=%u dev=%u:%u",st.st_mode,st.st_uid,st.st_gid,major(st.st_rdev),minor(st.st_rdev));
    puts("");
    if(r || !S_ISCHR(st.st_mode))return;
    int fd=open(path,O_RDWR|O_CLOEXEC);e=errno;
    printf("DISPLAY848_ROOT_PROBE path=%s open=%d errno=%d not_service_permission_test=1\n",path,fd,e);
    if(fd<0)return;
    struct fb_fix_screeninfo f={0};struct fb_var_screeninfo v={0};
    int a=ioctl(fd,FBIOGET_FSCREENINFO,&f);int ae=errno;
    int b=ioctl(fd,FBIOGET_VSCREENINFO,&v);int be=errno;
    printf("DISPLAY848_FB fixed=%d errno=%d variable=%d errno=%d x=%u y=%u bpp=%u stride=%u size=%u\n",a,ae,b,be,v.xres,v.yres,v.bits_per_pixel,f.line_length,f.smem_len);
    close(fd);
}
static void display_observe(void) {
    const unsigned waits[]={20,40,60};
    for(unsigned round=0;round<3;round++) {
        sleep(waits[round]);printf("DISPLAY848_SNAPSHOT round=%u\n",round);
        display_node("/dev/fb0");display_node("/dev/graphics/fb0");
        DIR *d=opendir("/proc");if(!d)continue;struct dirent *de;
        while((de=readdir(d))) {
            if(de->d_name[0]<'0'||de->d_name[0]>'9')continue;
            char path[512],line[2048];
            snprintf(path,sizeof(path),"/proc/%.32s/comm",de->d_name);
            FILE *fp=fopen(path,"r");if(!fp)continue;
            char comm[64]={0};char *got=fgets(comm,sizeof(comm),fp);fclose(fp);

            if(got && strstr(comm,"sh")) {
                char command[4096]={0};
                snprintf(path,sizeof(path),"/proc/%.32s/cmdline",de->d_name);
                int cfd=open(path,O_RDONLY|O_CLOEXEC);
                ssize_t count=cfd<0?-1:read(cfd,command,sizeof(command)-1);
                if(cfd>=0)close(cfd);
                if(count>0) {
                    for(ssize_t k=0;k<count;k++)if(!command[k])command[k]=' ';
                    if(strstr(command,"direct-desktop-861")||strstr(command,"lab-explicit-start")) {
                        printf("DIRECT864_PROCESS pid=%s comm=%s cmd=%s\n",de->d_name,comm,command);
                        snprintf(path,sizeof(path),"/proc/%.32s/status",de->d_name);fp=fopen(path,"r");
                        if(fp){while(fgets(line,sizeof(line),fp))if(!strncmp(line,"Uid:",4)||!strncmp(line,"Gid:",4))printf("DIRECT864_ID pid=%s %s",de->d_name,line);fclose(fp);}
                        snprintf(path,sizeof(path),"/proc/%.32s/root/data/local/tmp/direct-desktop-861.log",de->d_name);
                        struct stat st;int r=stat(path,&st);printf("DIRECT864_LOG pid=%s stat=%d errno=%d\n",de->d_name,r,errno);
                        snprintf(path,sizeof(path),"/proc/%.32s/fd/1",de->d_name);
                        ssize_t z=readlink(path,line,sizeof(line)-1);if(z>=0){line[z]=0;printf("DIRECT864_STDOUT pid=%s target=%s\n",de->d_name,line);}
                    }
                }
            }

            if(!got||!strstr(comm,"composer"))continue;
            printf("DISPLAY848_COMPOSER pid=%s comm=%s",de->d_name,comm);
            snprintf(path,sizeof(path),"/proc/%.32s/maps",de->d_name);fp=fopen(path,"r");
            if(fp){while(fgets(line,sizeof(line),fp))if(strstr(line,"composer")||strstr(line,"/dev/"))printf("DISPLAY848_MAP %s",line);fclose(fp);}
            snprintf(path,sizeof(path),"/proc/%.32s/status",de->d_name);fp=fopen(path,"r");
            if(fp){while(fgets(line,sizeof(line),fp))if(!strncmp(line,"Uid:",4)||!strncmp(line,"Gid:",4)||!strncmp(line,"Groups:",7))printf("DISPLAY848_ID %s",line);fclose(fp);}
            snprintf(path,sizeof(path),"/proc/%.32s/root/dev/graphics/fb0",de->d_name);display_node(path);
        }
        closedir(d);fflush(stdout);
    }
    _exit(0);
}

